import{_ as t,o as e,c as r,ag as l}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"408 统考操作系统 (Operating System) —— 知识库总览","description":"","frontmatter":{},"headers":[],"relativePath":"操作系统/index.md","filePath":"操作系统/index.md","lastUpdated":1777091574000}'),i={name:"操作系统/index.md"};function o(n,a,s,h,_,d){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="_408-统考操作系统-operating-system-——-知识库总览" tabindex="-1">408 统考操作系统 (Operating System) —— 知识库总览 <a class="header-anchor" href="#_408-统考操作系统-operating-system-——-知识库总览" aria-label="Permalink to &quot;408 统考操作系统 (Operating System) —— 知识库总览&quot;">​</a></h1><blockquote><p>本资料库汇集了 408 考研《操作系统》科目的全部核心大纲知识点、重难点梳理汇编及考频分析，涵盖操作系统概述、进程管理、内存管理、文件管理和输入输出管理五大板块。</p></blockquote><hr><h2 id="📂-理论模块" tabindex="-1">📂 理论模块 <a class="header-anchor" href="#📂-理论模块" aria-label="Permalink to &quot;📂 理论模块&quot;">​</a></h2><p>基于王道考研讲义与多源笔记深度融合，按考试大纲章节编排：</p><ul><li><strong><a href="./01_操作系统概述.html">01_操作系统概述</a></strong>：操作系统的概念、特征、功能；发展与分类；运行环境（内核态/用户态/中断/系统调用）；大内核与微内核。</li><li><strong><a href="./02_进程管理.html">02_进程管理</a></strong>：进程与线程概念、状态转换；进程同步与互斥（信号量/管程/经典问题）；处理机调度算法；死锁的预防、避免与检测。</li><li><strong><a href="./03_内存管理.html">03_内存管理</a></strong>：程序装入与链接；连续/非连续分配（分页/分段/段页式）；虚拟内存（请求分页/页面置换算法/抖动/工作集）。</li><li><strong><a href="./04_文件管理.html">04_文件管理</a></strong>：文件逻辑结构与物理结构；目录结构；文件存储空间管理；文件共享与保护。</li><li><strong><a href="./05_输入输出管理.html">05_输入输出管理</a></strong>：I/O 控制方式；I/O 软件层次；缓冲区管理；设备分配与回收；SPOOLing 技术；磁盘调度算法。</li></ul><h2 id="🎯-提分与回顾" tabindex="-1">🎯 提分与回顾 <a class="header-anchor" href="#🎯-提分与回顾" aria-label="Permalink to &quot;🎯 提分与回顾&quot;">​</a></h2><ul><li><strong><a href="./06_考频与重难点总结.html">06_考频与重难点总结</a></strong>：包含操作系统各章节选择题高频考点套路、计算题核心模型（银行家算法、页面置换、磁盘调度）及易错辨析。</li></ul><hr><h2 id="💡-备考建议" tabindex="-1">💡 备考建议 <a class="header-anchor" href="#💡-备考建议" aria-label="Permalink to &quot;💡 备考建议&quot;">​</a></h2><ol><li>操作系统的核心在于【进程管理】和【内存管理】两大章节，占整科分值约 60%。进程同步中的 PV 操作和信号量机制是大题重灾区，务必手动推导经典同步问题。</li><li>内存管理中的地址变换计算（页表查询、缺页处理流程）需要结合计组的存储体系知识理解，建议两科联合复习。</li><li>文件管理与 I/O 管理以选择题为主，但磁盘调度算法的计算题也有考查，注意区分 SCAN/C-SCAN/LOOK 等变种。</li></ol>',11)])])}const p=t(i,[["render",o]]);export{c as __pageData,p as default};
